mapper.update:
UPDATE pur_purchase_order SET status=#{nextState},version=version+1,
      approver_user_id=COALESCE(#{approverUserId},approver_user_id),approved_at=COALESCE(#{approvedAt},approved_at),updated_at=#{at}
      WHERE tenant_id=#{tenantId} AND order_id=#{orderId} AND status=#{expectedState} AND version=#{expectedVersion}

UPDATE pur_receipt SET status='CONFIRMED',source_event_id=#{sourceEventId},
      confirmed_at=#{at},version=version+1,updated_at=#{at}
      WHERE tenant_id=#{tenantId} AND receipt_id=#{receiptId} AND status='DRAFT' AND version=#{expectedVersion}

UPDATE pur_purchase_return SET status=#{nextState},version=version+1,updated_at=#{at}
      WHERE tenant_id=#{tenantId} AND purchase_return_id=#{purchaseReturnId}
        AND status=#{expectedState} AND version=#{expectedVersion}

UPDATE pur_purchase_return SET status='POSTED',source_event_id=#{sourceEventId},
      approver_user_id=#{approverUserId},posted_at=#{at},version=version+1,updated_at=#{at}
      WHERE tenant_id=#{tenantId} AND purchase_return_id=#{purchaseReturnId}
        AND status='PENDING_APPROVAL' AND version=#{expectedVersion}
